        </filter>
        <filter id="vnwb-paper" x="0" y="0" width="100%" height="100%">
            <feTurbulence type="fractalNoise" baseFrequency="0.85" numOctaves="2" seed="2" result="t" />
            <feColorMatrix in="t" type="matrix"
                values="0 0 0 0 0.42  0 0 0 0 0.38  0 0 0 0 0.30  0 0 0 0.9 -0.32" />
        </filter>
        <linearGradient id="vnwb-fadeb-g" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0.86" stop-color="#fff" />
            <stop offset="1" stop-color="#000" />
